grammar Expr;
prog:   expr EOF ;
expr:   expr ('*'|'/') expr  # MulDiv
    |   expr ('+'|'-') expr  # AddSub
    |   INT                  # Int
    |   '(' expr ')'         # Parens
    ;
INT :   [0-9]+ ;
WS  :   [ \t\r\n]+ -> skip ;

