Lexer - scanner.ejemplo:
Token next_token(Lexer *l) {
    skip_whitespace_and_comments(l);
    uint32_t start = l->pos;
    char c = advance(l);
    if (isalpha(c) || c == '_') return scan_ident_or_kw(l, start);
    if (isdigit(c)) return scan_number(l, start);
    if (c == '=' && peek(l) == '=') { advance(l); return make_tok(TOK_EQ, start, l->pos); }
    return make_tok(single_char_kind(c), start, l->pos);
}

